const f = $input.first().json;
let raw = String(f['Target URL'] || '').trim();
const chatId = String(f['Telegram Chat ID'] || '').trim();
const auth = String(f['Authorization'] || '');
if (raw && raw.indexOf('://') === -1) raw = 'https://' + raw;
let valid = false;
let reason = '';
let domain = '';
let origin = '';
let targetUrl = raw;
try {
  const idx = raw.indexOf('://');
  if (idx < 1) throw new Error('bad url');
  const scheme = raw.slice(0, idx).toLowerCase();
  const rest = raw.slice(idx + 3);
  let cut = rest.length;
  ['/', '?', '#'].forEach((c) => { const p = rest.indexOf(c); if (p > -1 && p < cut) cut = p; });
  const hostPort = rest.slice(0, cut).toLowerCase();
  const path = rest.slice(cut) || '/';
  if (hostPort.indexOf('@') > -1 || !hostPort) throw new Error('bad url');
  const h = hostPort.split(':')[0];
  const u = { protocol: scheme + ':', host: hostPort, toString: () => scheme + '://' + hostPort + path };
  const privateIp = h === 'localhost' || h.startsWith('127.') || h.startsWith('10.') || h.startsWith('192.168.') || h.startsWith('169.254.') || h.startsWith('0.') || /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(h) || h.endsWith('.local') || h.endsWith('.internal');
  if (u.protocol !== 'http:' && u.protocol !== 'https:') reason = 'Only http and https URLs are supported.';
  else if (!/^[a-z0-9.-]+$/.test(h) || h.indexOf('.') === -1) reason = 'The domain name is not valid.';
  else if (privateIp) reason = 'Local and private addresses cannot be scanned.';
  else if (auth.indexOf('Yes') !== 0) reason = 'Authorisation to test the target was not confirmed.';
  else if (!chatId) reason = 'Telegram chat ID is missing.';
  else { valid = true; domain = h; origin = u.protocol + '//' + u.host; targetUrl = u.toString(); }
} catch (e) {
  reason = 'The value entered is not a parsable URL.';
}
const scanDate = new Date().toISOString().slice(0, 10);
return [{ json: { valid, reason, input: raw, targetUrl, domain, origin, httpUrl: 'http://' + domain + '/', chatId, scanDate } }];

const g = (n) => { try { return $(n).first().json; } catch (e) { return { error: { message: 'no data' } }; } };
const v = $('Validate URL').first().json;
const st = g('Check HTTP Status and Redirect');
const hd = g('Check Security Headers');
const ck = g('Check Cookie Flags');
const rb = g('Fetch robots.txt');
const sm = g('Fetch sitemap.xml');
const ssl = g('Check SSL/TLS');
const dns = g('DNS and IP Lookup');
const findings = [];
const add = (category, title, severity, evidence, impact, remediation) => {
  findings.push({ id: 'VAPT-' + String(findings.length + 1).padStart(3, '0'), category, title, severity, evidence: String(evidence).slice(0, 300), impact, remediation });
};
const hdrs = (r) => (r && r.headers) ? r.headers : {};
const isHttps = v.targetUrl.indexOf('https://') === 0;
const reachable = hd && hd.statusCode !== undefined && !hd.error;

// 1. Reachability and redirects
if (!reachable) {
  add('Availability', 'Target unreachable', 'High', (hd.error && hd.error.message) || 'No response received', 'The site could not be assessed; it may be down or blocking automated requests.', 'Verify availability and allow-list the scanner if intended.');
} else {
  add('Availability', 'Target reachable', 'Info', 'HTTP ' + hd.statusCode + ' from ' + v.targetUrl, 'None.', 'No action required.');
}
if (st.error || st.statusCode === undefined) {
  add('Transport', 'Plain HTTP (port 80) not reachable', 'Info', (st.error && st.error.message) || 'No response', 'HTTP is not served, which is acceptable if HTTPS is enforced.', 'No action required.');
} else {
  const loc = String(hdrs(st).location || '');
  if (st.statusCode >= 300 && st.statusCode < 400 && loc.indexOf('https://') === 0) {
    add('Transport', 'HTTP redirects to HTTPS', 'Info', 'HTTP ' + st.statusCode + ' -> ' + loc, 'None.', 'No action required.');
  } else {
    add('Transport', 'HTTP does not redirect to HTTPS', 'High', 'HTTP ' + st.statusCode + ' Location: ' + (loc || 'none'), 'Users reaching the site over HTTP can be intercepted or downgraded (man-in-the-middle).', 'Redirect all HTTP traffic to HTTPS with a 301 and enable HSTS.');
  }
}

// 2. Security headers
if (reachable) {
  const h = hdrs(hd);
  if (isHttps && !h['strict-transport-security']) add('Headers', 'Missing Strict-Transport-Security (HSTS)', 'High', 'Header absent', 'Browsers may be tricked into using HTTP, enabling SSL-stripping attacks.', 'Add Strict-Transport-Security: max-age=31536000; includeSubDomains.');
  if (!h['content-security-policy']) add('Headers', 'Missing Content-Security-Policy', 'Medium', 'Header absent', 'No browser-side mitigation against XSS and content injection.', 'Define a restrictive Content-Security-Policy.');
  if (!h['x-frame-options'] && String(h['content-security-policy'] || '').indexOf('frame-ancestors') === -1) add('Headers', 'Missing clickjacking protection (X-Frame-Options)', 'Medium', 'X-Frame-Options and CSP frame-ancestors absent', 'The site can be framed by a malicious page (clickjacking).', 'Add X-Frame-Options: DENY or CSP frame-ancestors.');
  if (!h['x-content-type-options']) add('Headers', 'Missing X-Content-Type-Options', 'Low', 'Header absent', 'Browsers may MIME-sniff responses.', 'Add X-Content-Type-Options: nosniff.');
  if (!h['referrer-policy']) add('Headers', 'Missing Referrer-Policy', 'Low', 'Header absent', 'Full URLs may leak to third parties through the Referer header.', 'Add Referrer-Policy: strict-origin-when-cross-origin.');
  if (!h['permissions-policy']) add('Headers', 'Missing Permissions-Policy', 'Info', 'Header absent', 'Browser features are not explicitly restricted.', 'Add a Permissions-Policy header.');
  if (h['server'] || h['x-powered-by']) {
    const disc = [h['server'] ? 'Server: ' + h['server'] : '', h['x-powered-by'] ? 'X-Powered-By: ' + h['x-powered-by'] : ''].filter(Boolean).join('; ');
    const hasVersion = /[0-9]+\.[0-9]+/.test(disc);
    add('Headers', 'Technology disclosure in headers', hasVersion ? 'Medium' : 'Low', disc, 'Version details help attackers select known exploits.', 'Remove or genericise Server and X-Powered-By headers.');
  }
  if (String(h['access-control-allow-origin'] || '') === '*') add('Headers', 'Permissive CORS policy (wildcard origin)', 'Medium', 'Access-Control-Allow-Origin: *', 'Any website can read responses from this origin.', 'Restrict allowed origins to trusted domains.');
}

// 3. Cookies
const rawCookies = hdrs(ck)['set-cookie'];
const cookies = rawCookies ? (Array.isArray(rawCookies) ? rawCookies : [rawCookies]) : [];
if (cookies.length === 0) {
  add('Cookies', 'No cookies set on landing page', 'Info', 'No Set-Cookie header observed', 'None.', 'No action required.');
}
cookies.forEach((c) => {
  const name = String(c).split('=')[0];
  const low = String(c).toLowerCase();
  if (isHttps && low.indexOf('secure') === -1) add('Cookies', 'Cookie "' + name + '" missing Secure flag', 'Medium', String(c).slice(0, 120), 'Cookie may be sent over unencrypted connections.', 'Set the Secure attribute.');
  if (low.indexOf('httponly') === -1) add('Cookies', 'Cookie "' + name + '" missing HttpOnly flag', 'Medium', String(c).slice(0, 120), 'Cookie is readable by JavaScript and exposed to XSS theft.', 'Set the HttpOnly attribute.');
  if (low.indexOf('samesite') === -1) add('Cookies', 'Cookie "' + name + '" missing SameSite attribute', 'Low', String(c).slice(0, 120), 'Increases exposure to CSRF.', 'Set SameSite=Lax or Strict.');
});

// 4. robots.txt / sitemap.xml
if (rb.statusCode === 200 && !rb.error) {
  const lines = String(rb.body || rb.data || '').split(String.fromCharCode(10));
  const keys = ['admin', 'backup', 'config', 'private', 'secret', 'internal', 'login', 'staging', 'test', 'db', 'api'];
  const sensitive = lines.filter((l) => l.toLowerCase().indexOf('disallow') === 0 && keys.some((k) => l.toLowerCase().indexOf(k) > -1)).map((l) => l.trim());
  if (sensitive.length) add('Information Disclosure', 'robots.txt reveals sensitive paths', 'Low', sensitive.slice(0, 8).join(' | '), 'Attackers can use disclosed paths as a map of interesting targets.', 'Do not rely on robots.txt for secrecy; protect paths with authentication.');
  else add('Information Disclosure', 'robots.txt present', 'Info', 'HTTP 200, ' + lines.length + ' lines', 'None.', 'No action required.');
} else {
  add('Information Disclosure', 'robots.txt not found', 'Info', 'HTTP ' + (rb.statusCode || 'n/a'), 'None.', 'No action required.');
}
if (sm.statusCode === 200 && !sm.error) add('Information Disclosure', 'sitemap.xml exposed', 'Info', 'HTTP 200, ' + String(sm.body || sm.data || '').length + ' bytes', 'Reveals site structure (normally intentional).', 'Confirm no private URLs are listed.');
else add('Information Disclosure', 'sitemap.xml not found', 'Info', 'HTTP ' + (sm.statusCode || 'n/a'), 'None.', 'No action required.');

// 5. SSL / TLS
if (ssl.error || ssl.statusCode === undefined) {
  const msg = (ssl.error && ssl.error.message) || 'No response';
  const certIssue = /certificate|SSL|TLS|self.signed|expired|altnames|handshake/i.test(msg);
  add('TLS', certIssue ? 'TLS certificate problem' : 'HTTPS not available', certIssue ? 'Critical' : 'High', msg, 'Visitors see browser warnings or traffic is unencrypted; trust is compromised.', 'Install a valid, trusted certificate matching the hostname and renew before expiry.');
} else {
  add('TLS', 'Valid TLS certificate and HTTPS connection', 'Info', 'HTTPS handshake succeeded with strict validation', 'None.', 'No action required.');
}

// 6. DNS
const answers = (dns && dns.Answer) ? dns.Answer.filter((a) => a.type === 1) : [];
if (dns.error || !answers.length) add('DNS', 'No A record resolved', 'High', 'DNS status ' + (dns.Status !== undefined ? dns.Status : 'error'), 'The domain may not resolve for users.', 'Check DNS configuration.');
else add('DNS', 'DNS resolves', 'Info', 'A: ' + answers.map((a) => a.data).join(', ') + ' (TTL ' + answers[0].TTL + 's)', 'None.', 'No action required.');

const order = ['Critical', 'High', 'Medium', 'Low', 'Info'];
findings.sort((a, b) => order.indexOf(a.severity) - order.indexOf(b.severity));
findings.forEach((f, i) => { f.id = 'VAPT-' + String(i + 1).padStart(3, '0'); });
const counts = {};
order.forEach((s) => { counts[s] = findings.filter((f) => f.severity === s).length; });
const overall = counts.Critical ? 'Critical' : counts.High ? 'High' : counts.Medium ? 'Medium' : counts.Low ? 'Low' : 'Info';
const fileName = 'VAPT_' + v.domain + '_' + v.scanDate;
return [{ json: { target: v.targetUrl, domain: v.domain, scanDate: v.scanDate, chatId: v.chatId, fileName, overallRisk: overall, severityCounts: counts, resolvedIps: answers.map((a) => a.data), finalStatus: hd.statusCode || null, findings } }];

const s = $('Score Findings').first().json;
const body = $input.first().json.reportHtml;
const css = 'body{font-family:Segoe UI,Arial,sans-serif;max-width:900px;margin:40px auto;color:#222;line-height:1.5}h1{color:#0b3d6b;border-bottom:3px solid #0b3d6b;padding-bottom:8px}h2{color:#0b3d6b;margin-top:32px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:6px 8px;text-align:left;font-size:13px;vertical-align:top}th{background:#0b3d6b;color:#fff}code{background:#f2f2f2;padding:1px 4px}';
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + s.fileName + '</title><style>' + css + '</style></head><body>' + body + '</body></html>';
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), s.fileName + '.html', 'text/html');
return [{ json: { fileName: s.fileName, chatId: s.chatId, overallRisk: s.overallRisk, domain: s.domain, counts: s.severityCounts }, binary: { data: binary } }];
